         not any(c in name for c in '\x00\r\n\t') and
         not PurePosixPath(name).is_absolute() and
         PurePosixPath(name).as_posix() == name and
         all(p not in ('','..','.') for p in name.split('/')),('normalized relative path',name))
    return name


def workspace(name):
